mutations.command:
config=$(vtysh -c 'show running-config') || exit $?
  n=$(printf '%s\n' "$config" | awk '$1=="neighbor" && $3=="remote-as" && $4==65999 {n++} END {print n+0}') || exit $?
  case "$n" in
    4) echo "Already in requested AS state" ;;
    0) vtysh -c 'conf t' -c 'router bgp 65201' -c 'neighbor 172.16.0.130 remote-as 65999' -c 'neighbor 172.16.0.146 remote-as 65999' -c 'neighbor 172.16.0.162 remote-as 65999' -c 'neighbor 172.16.0.178 remote-as 65999' -c end ;;
    *) echo "Unexpected partial AS state" >&2; exit 2 ;;
  esac

